1	(function () {
2	  'use strict';
3	  const R=window.Reopening, C=window.City;
4	  const $=id=>document.getElementById(id);
5	  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
6	  const SAVE_KEY='ab_reopening_v1';
7	  const ui={selected:null,beer:'blond',premium:false,modal:null,returnFocus:null,brewElapsed:0,sound:true,tutorialSeen:false,signature:'',lastFrame:performance.now(),lastSave:0,noticeTimer:null,audio:null,city:C.create(),cityPath:[],cityTarget:null,cityMode:'map',cityPlace:'pub',cityNear:'pub',cityFerry:false,cityZoom:1,cityCamera:'street',hintDismissed:false,cityKeys:new Set(),cityFrame:performance.now(),notebook:false};
8	  let state=R.createGame(seedFromUrl());
9	  let restored=false,saveError=false;
10	  try {
11	    const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');
12	    if(saved){const valid=R.restore(saved.game||saved);if(valid){state=valid;ui.city=C.restore(saved.city);restored=state.phase!=='welcome';ui.tutorialSeen=Boolean(saved.tutorialSeen);ui.sound=saved.sound!==false;ui.brewElapsed=state.phase==='brew'&&Number.isFinite(saved.brewElapsed)?Math.max(0,Math.min(6,saved.brewElapsed)):0;}else saveError=true;}
13	  } catch {saveError=true;}
14	  const scene=new PubScene($('pub-canvas'));
15	  const backstage=new BackstageUI({canvas:$('pub-canvas'),getState:()=>state,dispatch,save,isPaused:()=>Boolean(ui.modal),showModal:modal,playBeat:()=>sound('beat')});
16	  const journey=new JourneyUI({canvas:$('pub-canvas'),getState:()=>state,dispatch,isPaused:()=>Boolean(ui.modal),playFeedback:()=>sound('bad'),tick:(seconds,input)=>{
17	    const result=R.act(state,{type:'journeyAction',verb:'tick',value:{seconds,...input}});
18	    if(result.ok)state=result.state;
19	  }});
20	  $('pub-canvas').tabIndex=0;
21	  const DAYS=['试营业，试着活着','好评与坏账','合法地重新开业'];
22	  const PORTRAITS={lotte:'👩🏻',bram:'🧔🏽',marta:'👩🏼‍🍳'};
23	  const PLACE_COPY={
24	    garden:{brief:'认路 / 包装台',quote:'花店关门以前，温室已经开始下一班。',detail:'温室日间侧门。'},
25	    pub:{brief:'酿酒 / 开门',quote:'这块招牌归你。招牌下面的土地，房东说另谈。',detail:'回到自家柜台。酿一批新酒，或者翻开营业牌。'},
26	    lotte:{brief:'留酒约定',quote:'桥不收过路费，所以大家还能在桥上碰面。',detail:'Lotte 在桥边排练。给她留一杯今晚的黑啤，她会在下一晚带来乐队。'},
27	    coffee:{brief:'帮工 / 夜店线索',quote:'招聘联合创始人。工作内容：洗杯子。工资照付。',detail:'Bram 的午市缺人。帮完这半天，拿 €18 现金，他今晚也愿意多等你一会儿。'},
28	    noord:{brief:'限时打捞',quote:'城市更新的意思是：旧东西先扔进水里。',detail:'渡轮尽头是北岸旧码头。借条船，30 秒打捞酒花和密封瓶；捞到单车得付清运费。'},
29	    market:{brief:'现货 / 卸货路线',quote:'没有滞销，只有尚未被发现的限量款。',detail:'收摊前买一箱现货：2 杯金色艾尔、1 杯黑啤，品质 1；比自己酿（€12 / 6 杯）便宜、也少拿 3 杯。当日价格与能省多少，看下面柜台的牌价。'},
30	    flowers:{brief:'配花 / 礼物 / 窗台',quote:'花保鲜三天。房租每天都很新鲜。',detail:'挑三枝郁金香，选包装。可以送给 Lotte，也可以把酒馆的窗台布置起来。'},
31	    lab:{brief:'酒花 / 温室线索',quote:'论文还在返修，酒花已经通过鼻审。',detail:'Chen 有两份多出来的试验酒花。材料费 €6；之后每酿一批消耗一份，品质提高一级，最高 3。也可以免费问问他温室漏水的事。'}
32	  };
33	  const $board=$('action-content');
34	
35	  function seedFromUrl(){const n=Number(new URLSearchParams(location.search).get('seed'));return Number.isSafeInteger(n)&&n>0?n:42;}
36	  function money(n){return '€'+Math.round(Number(n)||0);}
37	  function save(){
38	    try{localStorage.setItem(SAVE_KEY,JSON.stringify({version:1,game:state,city:ui.city,brewElapsed:ui.brewElapsed,tutorialSeen:ui.tutorialSeen,sound:ui.sound}));$('save-status').textContent='进度已保存在这台设备';}
39	    catch{$('save-status').textContent='当前浏览器无法保存 · 请保持页面打开';}
40	  }
41	  function sound(kind='tap'){
42	    if(!ui.sound)return;
43	    try{
44	      const AudioContext=window.AudioContext||window.webkitAudioContext;
45	      if(!AudioContext)return;
46	      ui.audio=ui.audio||new AudioContext();
47	      if(ui.audio.state==='suspended')ui.audio.resume().catch(()=>{});
48	      const now=ui.audio.currentTime;
49	      const notes=kind==='beat'?[70,105]:kind==='good'?[523.25,659.25,783.99]:kind==='bad'?[196,164.81]:[392];
50	      notes.forEach((freq,i)=>{const osc=ui.audio.createOscillator(),gain=ui.audio.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,now+i*.07);gain.gain.linearRampToValueAtTime(.04,now+i*.07+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.07+.21);osc.connect(gain);gain.connect(ui.audio.destination);osc.start(now+i*.07);osc.stop(now+i*.07+.23);});
51	    }catch{/* Audio never blocks game actions. */}
52	  }
53	  function notify(message,bad=false){
54	    if(!message)return;
55	    clearTimeout(ui.noticeTimer);$('notice').textContent=message;$('notice').className='notice visible'+(bad?' bad':'');
56	    ui.noticeTimer=setTimeout(()=>$('notice').classList.remove('visible'),4300);
57	  }
58	  function dispatch(action){
59	    if(ui.modal)return;
60	    const previous=state.phase,previousDay=state.day;
61	    const result=R.act(state,action);
62	    if(!result.ok){notify(result.message||'现在无法这样操作。',true);return;}
63	    state=result.state;
64	    if(action.type==='journeyStart'){ui.city=C.parkBike(ui.city);ui.cityKeys.clear();ui.cityPath=[];ui.cityTarget=null;journey.clear();}
65	    if(action.type==='journeyReturn'){ui.cityMode='place';ui.cityPlace='flowers';journey.clear();}
66	    if(action.type==='explore'){ui.city=C.parkBike(ui.city);ui.cityKeys.clear();ui.cityPath=[];backstage.clear();backstage.signature='';backstage.overview=false;}
67	    if(action.type==='returnExplore'){homeOnFoot();ui.cityMode='place';}
68	    if(action.type==='start'||state.day!==previousDay){homeOnFoot();ui.cityMode='map';ui.cityCamera='street';}
69	    if(previous==='night'&&state.phase==='summary'){homeOnFoot();ui.cityMode='map';ui.cityCamera='street';}
70	    if(action.type==='prepare'&&action.kind==='brew')ui.brewElapsed=0;
71	    if(action.type==='brewHit')ui.brewElapsed=0;
72	    if(action.type==='serve'||action.type==='water')ui.selected=null;
73	    if(action.type==='serve')ui.tutorialSeen=true;
74	    if(result.message)notify(result.message);
75	    sound(['serve','brewHit','upgrade','finish'].includes(action.type)?'good':'tap');
76	    save();render();
77	    if(action.type==='explore'||action.type==='journeyStart'){$('pub-canvas').scrollIntoView({block:'center',behavior:'auto'});$('pub-canvas').focus({preventScroll:true});}
78	    if(action.type==='start'||state.day!==previousDay)window.scrollTo({top:0,behavior:'auto'});
79	    if(previous!==state.phase&&matchMedia('(max-width: 800px)').matches&&['brew','forage','summary','ending'].includes(state.phase))$('action-content').scrollIntoView({behavior:'auto',block:'start'});
80	    syncEvent();
81	  }
82	  function modal(kicker,title,body,buttons,kind='normal'){
83	    ui.cityKeys.clear();
84	    backstage.clear();
85	    journey.clear();
86	    ui.returnFocus=document.activeElement;
87	    ui.modal={kicker,title,body,buttons,kind};
88	    $('dialog-kicker').textContent=kicker;$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;
89	    $('dialog-actions').innerHTML=buttons.map((b,i)=>`<button class="${b.secondary?'secondary':'primary'}" data-modal-action="${i}" ${b.disabled?'disabled':''}>${esc(b.label)}${b.description?`<small>${esc(b.description)}</small>`:''}</button>`).join('');
90	    $('overlay').hidden=false;
91	    $('dialog-actions').querySelector('button:not(:disabled)').focus();
92	    updateMeters();
93	  }
94	  function closeModal(){ui.modal=null;$('overlay').hidden=true;ui.lastFrame=performance.now();if(ui.returnFocus?.isConnected)ui.returnFocus.focus({preventScroll:true});}
95	  // Short, non-blocking local cue for the very first pour (night 1). Full
96	  // instructions remain in the H help modal; P still pauses with restart.
97	  function firstGuestCue(){
98	    if(ui.tutorialSeen||state.day!==1||state.phase!=='night')return '';
99	    return '<div class="first-guest-cue"><span class="board-eyebrow">第一杯 · 三步</span><ol><li><em>1</em><b>选中客人</b>（第一位 Marta 已为你选好）</li><li><em>2</em> 核对她想喝的酒，点「<b>开始倒酒 · E</b>」</li><li><em>3</em> 指针进浅绿区，点「<b>收杯 · Space</b>」</li></ol><button class="text-button" data-action="tutorial-dismiss">知道了，开始营业</button></div>';
100	  }
101	  function syncEvent(){
102	    if(ui.modal||state.phase!=='night')return;
103	    if(state.night.event?.status!=='pending'){
104	      const story=R.stories.nightView(state,R.trade.available);if(!story)return;
105	      modal('白天的约定 · 阅读与选择时暂停',story.title,`<p class="event-quote">“${esc(story.quote)}”</p><p>现金 ${money(state.cash)}。回应与实际供酒分别记录，不自动增加好感或音乐收益。</p>`,story.choices.map(c=>({label:c.label,description:c.detail,disabled:c.disabled,secondary:['talk','regular','water'].includes(c.id),run:()=>dispatch({type:'storyNight',choice:c.id})})),'event');
106	      return;
107	    }
108	    const event=R.NIGHT_EVENTS[state.night.event.id],stock=state.batches.reduce((sum,b)=>sum+R.trade.available(state,b),0);
109	    modal('UNINVITED · 阅读与选择时暂停',event.title,`<p class="event-quote">“${esc(event.quote)}”</p><p>手头 ${money(state.cash)} · 还剩 ${stock} 杯酒。所有费用会计入今晚的账。</p>`,event.choices.map(choice=>({
110	      label:choice.label,description:choice.description,
111	      disabled:choice.id==='comp'?stock<1:choice.id==='samples'?stock<2:choice.id==='paperwork'?state.cash<10:false,
112	      secondary:choice.id==='refuse'||choice.id==='tasting',run:()=>dispatch({type:'event',choice:choice.id})
113	    })),'event');
114	  }
115	  function showHelp(){
116	    if(ui.modal)return;
117	    if(state.phase==='journey'){modal('城市出行 · 阅读时暂停','带着一件东西和一个约定出门。','<p>花店委托占一次准备，途中不重复扣行动。WASD / 方向键移动，B 在车旁上下车，E 取放花束。自动行进会沿选定路线走，关键选择暂停。</p><p>近路的石板上快骑会伤花，软垫能保护；平路更长。街头冲突可交涉或绕开，选择对抗后用 Space 闪避、J 格挡／硬直时反击。手持花不能格挡。</p><p>列车采用虚构票务规则：每段 €4，无票遇检查另加 €8。返程可以记账买票，不必被迫逃票。票务待付会从委托收入中偿还，并影响最终净余额。</p><p>失败可说明情况或退回花，不能重复领奖。货物与自行车有位置；必须带车回花店才结算。</p>',[{label:'继续这一趟'}]);return;}
118	    if(state.phase==='explore'){
119	      const street=Backstage.streetInfo?.(state.backstage.run);
120	      const streetHelp=street?`<p><b>今晚 · ${esc(street.title)}</b><br>${esc(street.description)} ${esc(street.hint)}</p>`:'';
121	      modal('CITY BACKSTAGE · 阅读时暂停','自动探索，重要的事你来选。',streetHelp+'<p><b>自动模式：</b>点选项或按对应数字键，角色会走到目的地、拾取和使用工具。拿箱子、交还人物、进入温室前会停下来；阅读时整条街和倒计时暂停。地图下方可切换 1× / 2× 播放或手动操作，途中可点“停下来，重新选路”。</p><p><b>手动模式：</b><kbd>WASD</kbd> / 方向键移动；鼠标瞄准，左键或 <kbd>J</kbd> 下钩，右键或 <kbd>F</kbd> 喷泡沫，<kbd>Space</kbd> 朝当前方向闪避。纯键盘和触屏操作会朝行走方向使用工具；方向按钮按住移动。</p>'+((street&&street.id!=="legacy")?'<p><b>空瓶引声：</b><kbd>N</kbd> 或空瓶按钮投向瞄准方向，每趟 3 瓶、间隔 2 秒。琥珀色声纹持续 5 秒，巡查和机器会循声过去；贴得太近仍会被追。<b>拖动空桶：</b>靠近青色圆环的空桶，按 <kbd>R</kbd> 抓住，再移动拖行；再按一次放下。拖桶会降速，先放下才可闪避。空桶挡路但不装进背包。木质酒桶仍是普通货物。</p>':'')+'<p>普通货物靠近自动装包，冷藏箱要靠近按 <kbd>E</kbd>。<kbd>Q</kbd> 扔下最后一件物品，腾出空间。也可以点「整理背包」，自己选放下哪一种。红灯街的 Noor 在西北，夜店在东侧，温室在东北。</p><p>机器头上的惊叹号预告冲撞，可以闪避、钩住或用泡沫打断。墙体会挡住工具；泡沫也会让你的脚步打滑。</p><p><kbd>M</kbd> 看全图。西南的回店口按 <kbd>E</kbd> 安全撤回，带走全包。收班或受伤过多只保住半包；轻装撤回放弃背包。已交付的箱子和发现的地方会保留。月雾不会成为酒或原料。</p>',[{label:'回到街区'}]);return;
122	    }
123	    modal('HOW TO PLAY · 阅读时暂停','照顾好今天，也准备好明天。',
124	      '<p><b>先逛城市。</b>WASD / 方向键移动，点击地点自动绕过运河和建筑，E 进入附近地点。B 在车旁骑车；宽桥直接骑，窄桥和渡轮推车过去，上岸后继续骑。花店可花 €4 和一次准备包三枝花，礼物和窗台都有用。去北岸走渡轮。逛地图免费，市场、咖啡馆和实验室可免费踩点，记下当晚路线、节拍与灌溉规律。办事才花行动。市场 €8 买 3 杯现货，实验室 €6 买 2 份酒花。</p><p><b>白天两次行动。</b>酿酒花 €12，得到 6 杯；帮咖啡店赚 €18；去北岸运河打捞酒花和押金瓶，躲开需要清运费的单车残骸；拜访 Lotte，答应今晚留给她一杯黑啤。</p>'+
125	      '<p><b>夜晚接待客人。</b>点击想先服务的人，核对口味和预算。每次开始倒酒消耗一杯库存；指针进入绿色区域再收杯。价格超过预算、口味不对或倒得太差，客人不会满意。</p>'+
126	      '<p><b>打烊后可以探险。每夜一趟，夜里的货留给下次营业；早上看景点手册背面的笔记。每晚都有麻烦。</b>房东、网红、检查员会提出要求。先看成本，再选应对方式；这时游戏暂停。基础租金 €18，事件会影响实际账单。</p><p><b>第三晚重开。</b>前两晚可选一件设备。最后留下至少 €100，并累计让 12 位客人满意。</p>'+
127	      '<p><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd> 选客人 · <kbd>E</kbd> 开始倒酒 · <kbd>Space</kbd> 收杯 / 酿造确认 / 打捞 · <kbd>A</kbd><kbd>D</kbd> 移动小船 · <kbd>P</kbd> 暂停 · <kbd>H</kbd> 帮助。所有操作也有可点击按钮。</p>'+
128	      '<p>没酒可以送杯水善后。失手也能继续；返回白天后，去咖啡店赚一笔备货钱。</p>',[{label:'回到酒吧'}]);
129	  }
130	  function pause(reason='歇口气，客人会等你。'){
131	    if(ui.modal)return;
132	    modal('PAUSED · 时间停止','暂时逃避现实。',`<p>${esc(reason)}</p><p>船、酒、客人的耐心都停在这里。<br>房东暂时也不能发明新费用。</p>`,[{label:'继续播放 / 回到街上'},{label:'重新开始这三天',secondary:true,run:()=>confirmRestart()}]);
133	  }
134	  function confirmRestart(){
135	    modal('NEW BEGINNING','重新开始这三天？','<p>当前三天的进度会被新一局替换。你可以继续使用这张相同的顾客安排。</p>',[{label:'保留进度，继续玩'},{label:'重新开始',secondary:true,run:()=>restart(state.seed)}]);
136	  }
137	  function restart(seed){state=R.createGame(seed);ui.selected=null;ui.beer='blond';ui.premium=false;ui.brewElapsed=0;ui.tutorialSeen=false;ui.city=C.create();ui.cityMode='map';ui.cityCamera='street';ui.hintDismissed=false;ui.cityPlace='pub';ui.cityPath=[];ui.cityTarget=null;save();render();window.scrollTo({top:0,behavior:'auto'});}
138	  const inCity=()=>['prep','summary'].includes(state.phase);
139	  const nearBike=()=>Math.hypot(ui.city.x-ui.city.bike.x,ui.city.y-ui.city.bike.y)<=42;
140	  const cityPlace=id=>id==='garden'?R.garden.ENTRY:C.PLACES[id];
141	  function cityView(){return {position:ui.city,path:ui.cityPath,target:ui.cityTarget,zoom:ui.cityZoom,camera:ui.cityCamera,mode:ui.cityMode,place:ui.cityPlace,afterHours:state.phase==='summary',notes:mapNotes(),bouquet:state.life.bouquet,display:state.life.display,garden:R.garden.context(state),flowerCart:ui.flowerCart||R.garden.CART};}
142	  function homeOnFoot(){const fresh=C.create();ui.city={...fresh,visited:ui.city.visited,bike:C.parkBike(ui.city).bike};ui.cityKeys.clear();ui.cityPath=[];ui.cityTarget=null;ui.cityPlace='pub';ui.cartFollowing=false;ui.flowerCart=null;ui.cartPath=[];}
143	
144	  function expeditionInvitation(){
145	    const used=state.prepared.includes('explore');
146	    if(state.phase==='prep')return '<p class="small-note">白天自由逛街 → 傍晚酒馆营业 → 打烊后，城市背面开门。出门不占明天的准备机会。</p>';
147	    return `<div class="expedition-invitation"><p class="board-eyebrow">00:40 / 城市背面</p><h3>${used?'这夜的收获，留给明天。':'游客睡了，这座城还没。'}</h3><p>超市后场、红灯街、夜店、失物分拣场与温室。选路线后自动走，关键事情停下来由你决定。每夜一趟。</p><button class="primary" data-action="expedition-launch" ${used?'disabled':''}>${used?'今晚已经探险过了':'带上工具，开始夜间探险 →'}</button></div>`;
148	  }
149	  function chooseExpedition(){
150	    if(state.phase!=='summary'||state.prepared.includes('explore'))return;
151	    const street=Backstage.streetInfo?.(Backstage.create(state.seed,state.day));
152	    const streetIntro=street?`<p><b>今晚 · ${esc(street.title)}</b><br>${esc(street.description)} ${esc(street.hint)}</p><p>超市有货架、冷库与可打开的卸货捷径；夜店有六秒鼓点掩护。分拣场可以停带、反转、钩货；温室能关阀抢时间，也能花零件修出后续夜晚的干路。每套工具都附带 3 只空瓶。引声带开巡查，或拖动青环空桶挡住冲撞；自动探索也能选择这两种做法。</p>`:'';
