512	    let person='lotte',text='这条运河连倒影都在涨房租。给我留杯黑的。';
513	    if(state.phase==='night'){const guest=selectedCustomer();if(guest){person=guest.person||guest.name;text=guest.quote;}}
514	    else if(state.music){person='lotte';text='你记得给我留的那杯酒。我也记得帮你叫上他们。';}
515	    else if(state.hops){person='bram';text='酒花留给下一桶。它们的香气不需要写申请。';}
