  function marketReceiptCard(v){
    switch(v.receipt){
      case 'available': {
        const errandLabel=v.canClaim
          ? (state.hops>=15
            ? '兑现回执 · 1 次行动 · 不花钱 → 3 杯品质 1 金色艾尔（酒花已满 15，不补、不折现金）'
            : '兑现回执 · 1 次行动 · 不花钱 → 3 杯品质 1 金色艾尔 +1 酒花（最多 15）')
          : '兑现回执 · 现在无法办理';
        return `<div class="upgrade-card" id="market-receipt-card"><strong>超市回执 · 可兑现</strong><p>${esc(v.reason)}</p>`+
          `<button class="primary" data-action="market-errand" ${v.canClaim?'':'disabled'}>${errandLabel}</button></div>`;
      }
      case 'pending':
        return `<div class="upgrade-card" id="market-receipt-card"><strong>超市回执 · 今晚先记账</strong><p class="small-note">${esc(v.reason)}</p></div>`;
      case 'claimed':
        return `<div class="upgrade-card" id="market-receipt-card"><strong>超市回执 · 已兑现</strong><p class="small-note">回执已经兑现过，不能重复领取。</p>`+
          `<button class="primary" data-action="market-errand" disabled>回执已兑现 · 不能重复领取</button></div>`;
      case 'expired':
        return `<div class="upgrade-card" id="market-receipt-card"><strong>超市回执 · 已过期</strong><p class="risk-note">${esc(v.reason)}</p></div>`;
      case 'final':
        return `<div class="upgrade-card" id="market-receipt-card"><strong>超市回执 · 无法兑现</strong><p class="risk-note">${esc(v.reason)}</p></div>`;
      default:return '';
    }
  }
  function marketPanel(){
    const v=R.marketInfo(state);
    const usedMarket=state.prepared.includes('market');
    const batchFull=state.batches.length+2>32;
    const buyDisabled=state.actions<1||usedMarket||state.cash<v.price||batchFull;
    const buyLabel=usedMarket?'今天已经进过货了':`买收摊酒箱 · ${money(v.price)} · 1 次行动`;
    let html=`<div class="upgrade-card" id="market-shift-card"><span class="board-eyebrow">免费情报 · 今晚的超市</span>`+
      `<strong>${esc(v.label)}</strong><p>${esc(v.clue)}</p><p class="small-note">看情报免费，不花行动、不改动今晚的结果；真办事才花钱花行动。</p></div>`;
    const savings=12-v.price;
    html+=`<div class="upgrade-card" id="market-crate-card"><strong>收摊酒箱 · ${money(v.price)}</strong>`+
      `<p>2 杯金色艾尔、1 杯运河黑啤，品质 1。比自己酿（€12 / 6 杯）少花 €${savings}，也少拿 3 杯。</p>`+
      (v.priceReason?`<p class="risk-note">${esc(v.priceReason)}</p>`:`<p class="small-note">今天是常规收摊价。</p>`)+
      `<button class="primary" data-action="prepare" data-kind="market" ${buyDisabled?'disabled':''}>${esc(buyLabel)}</button>`+
      (usedMarket?'<p class="small-note">现货已收进库存，每天只进一次。</p>':
        batchFull?'<p class="small-note">库存批次已满（32 批），先用掉一些再进货。</p>':
        state.actions<1?'<p class="small-note">今天的行动已用完，现货只能明天再来。</p>':
        state.cash<v.price?'<p class="small-note">手头的钱不够；Bram 的咖啡午市还在招临时工。</p>':'')+`</div>`;
    if(state.day<3){
      const nextDay=state.day+1;
      html+=`<p class="promise-note">夜里两条路：直接去货架或冷库拿货，货立刻进背包，但次日（第 ${nextDay} 天）这箱涨价 €2（只涨第 ${nextDay} 天）；或者亲手把滚动酒桶送到柜台、安全撤离，不碰库存，次日（第 ${nextDay} 天）白天花 1 次行动来跑不发工资的补班，换回 3 杯品质 1 的金色艾尔和 1 份酒花（最多 15）。</p>`;
    } else {
      html+='<p class="risk-note">第 3 夜是最后一夜，没有第 4 天：今夜直接去货架/冷库拿货，货入包就是全部收益，价格不会再涨；把酒桶送到柜台，也换不到能兑现的补班回执。眼前这个价格，就是今夜最后的价格。</p>';
    }
    html+=marketReceiptCard(v);
    return html;
  }
  const tripLabel={day:'夜次',status:'结果',cups:'剩杯',hops:'酒花',cash:'现金',visited:'路线',outcomes:'记事',extracted:'安全回店',bailed:'轻装撤回',rescued:'获救，保住半包',market:'超市',redlight:'红灯街',club:'夜店',sorting:'分拣场',greenhouse:'温室','market-salvaged':'收过超市货物','market-shortcut':'打开卸货捷径','club-backstage':'走过夜店后台','sorting-stopped':'传送带停过','sorting-reversed':'倒转分拣带','greenhouse-valve':'阀门关闭十二秒','greenhouse-repaired':'修好水泵，后续夜晚保留'};
  function tripWord(v){return tripLabel[v]||String(v??'');}
  function tripList(v){return (Array.isArray(v)?v:[v]).filter(Boolean).map(x=>esc(tripWord(x))).join('、');}
  function cityNotebook(){
    if(!ui.notebook)return '';
    const journal=Array.isArray(state.backstage?.journal)?state.backstage.journal:[];
    const trips=journal.slice(-3).reverse().map(t=>{
      if(!t||typeof t!=='object')return '';
      const status=tripWord(t.status||'bailed'), visited=tripList(t.visited), outcomes=tripList(t.outcomes);
      return `<li><strong>第 ${esc(t.day??'?')} 夜 · ${esc(status)}</strong><br>带回 ${esc(t.cups??0)} 杯酒 · ${esc(t.hops??0)} 份酒花 · ${money(Number(t.cash)||0)}<br><span>${visited?visited:'未到地点'}${outcomes?'｜'+outcomes:''}</span></li>`;
    }).join('');
    return `<div class="city-notebook"><p class="board-eyebrow">景点手册 / 正面给游客，背面留给自己</p><p>北岸渡轮 · 运河桥 · 南街花市。点击下方地点就能实际走过去。宽桥可以骑；窄桥和渡轮推车通过，上岸后继续骑。按 B 或进店才会停好车。</p><strong>地图背面的笔记</strong><ul>${mapNotes().length?mapNotes().map(n=>'<li>'+esc(n)+'</li>').join(''):'<li>夜里亲自走过的地方，才会写在这里。</li>'}</ul><strong>最近几趟夜路</strong><ul class="trip-log">${trips||'<li>还没有夜探记录。打烊后出门，回来把故事写在这里。</li>'}</ul>${journeyHistory()}</div>`;
  }
  function journeyHistory(){return '<strong>白天出行后记</strong><ul class="journey-history">'+(state.journeys.history.map(t=>`<li>第 ${t.day} 天 · ${t.kind==='rail'?'远郊展厅':'桥边送花'} · ${Journey.LABELS[t.outcome]}<br>花束 ${t.quality}/100 · 报酬 €${t.reward} · 已付交通 €${t.paid}<br>${esc(t.note)}${t.help?'<br>同行人记得你帮忙收过纸袋。':''}</li>`).join('')||'<li>还没有出行记录。带车去南街花店看看委托。</li>')+'</ul>'+R.trade.notes(state).map(n=>'<p class="promise-note">'+esc(n)+'</p>').join('');}
  function contractPanel(){
    const c=state.trade.contracts.find(c=>['offered','accepted'].includes(c.status));if(!c)return '';
    const detail=R.trade.brief(state,c);
    const button=(label,choice,batchId)=>`<button class="secondary" data-action="contract" data-id="${esc(c.id)}" data-choice="${choice}" ${batchId?`data-batch="${esc(batchId)}"`:''}>${esc(label)}</button>`;
    let html=`<div class="journey-invitation"><h3>${esc(detail.label)} · 第 ${c.dueDay} 晚${c.dueDay===state.day?'（今晚）':'（明晚）'}</h3><div class="contract-checklist"><span>${R.trade.LABELS[c.status]}</span><span>黑啤 1 杯 / 品质 ≥ ${detail.quality}</span><span>约定 €${detail.price} / 满意 +€2</span><span>${detail.pouring?'正在倒酒':detail.reserved?'已保护 1 杯':detail.missing?'缺合格黑啤 1 杯':'库存达标，未预留'}</span></div><p class="promise-note">下一步：${esc(detail.next)}</p><details><summary>交接来由与条款</summary><p>管理员：“${esc(R.trade.memory(state,c))}”</p><p>倒酒与品质小费照常。${c.dueDay===3?'最晚第三晚兑现。':''} 与 Lotte 留酒换音乐是两份不同约定。</p></details>`;
    if(c.status==='offered')return html+'<p>不占准备次数，但要为它备酒。没答应不算失约，开门后未答复的邀请自动结束。</p>'+button('答应这张预订单','accept')+button('这次只接送花，不供酒','decline')+'</div>';
    const reserved=state.batches.find(b=>b.id===c.reservedBatch);
    if(reserved)html+=`<p>已预留 1 杯 · 品质 ${reserved.quality} / 3${reserved.aged?' · 陈酿':''}</p>`;
    if(!state.night?.pours.some(p=>p.customerId===c.customerId)){
      html+=state.batches.filter(b=>b.beer==='stout'&&b.quality>=detail.quality&&b.cups>0&&b.id!==c.reservedBatch).map(b=>button('预留第 '+b.madeDay+' 天批次 · 品质 '+b.quality+' · 剩 '+b.cups+' 杯','reserve',b.id)).join('');
      if(reserved)html+=button('释放这一杯，保留订单','release');
      html+=button('说明缺货，免费协商取消','cancel');
    }
    return html+'</div>';
  }
  function selectedBatch(guest){
    const candidates=state.batches.filter(b=>b.beer===ui.beer&&R.trade.available(state,b,guest?.id)>0);
    const c=guest&&R.trade.forGuest(state,guest.id);
    return candidates.find(b=>b.id===ui.batchId)||candidates.find(b=>c&&b.id===c.reservedBatch)||candidates.find(b=>c&&b.quality>=R.trade.terms(state,c).quality)||candidates[0]||null;
  }
  function journeyInvitation(){
    const disabled=state.actions<1||state.journeys.usedDay===state.day||Boolean(state.life.bouquet)||!nearBike();
    return `<div class="journey-invitation"><h3>替花店跑一趟</h3><p>每日一份委托，占 1 次准备；花由店主提供。装载、选路、送达后带车返回，不影响原有私人配花。</p><button class="primary" data-action="journey-start" data-kind="delivery" ${disabled?'disabled':''}>桥边送花 · 自行车与街头遭遇</button><button class="secondary" data-action="journey-start" data-kind="rail" ${disabled?'disabled':''}>远郊展厅送花 · 虚构 NS 往返</button><p class="small-note">${!nearBike()?'先把停好的自行车带到花店。':state.life.bouquet?'先送出或布置你自己的花束。':state.journeys.usedDay===state.day?'今天的委托已经接过。':'近路有可绕开的冲突；铁路有买票路线。普通漫游仍免费。'}</p></div>`;
  }
  function sleepPanel(){
    const report=state.reports[state.reports.length-1];
    return `<details class="night-ledger"><summary>今晚营业账 · ${report.served} 杯 / 收入 ${money(report.earned)}</summary>${receipt(report)}<p>${esc(report.note)}</p><p>深夜另带回 ${money(state.backstage.cashAfterClose)}；现在手头 ${money(state.cash)}。</p></details>`+
      (state.day<3?'<details class="night-ledger"><summary>睡前改造酒馆 · 免费选一件，直接到明早</summary>'+Object.values(R.UPGRADES).filter(u=>!state.upgrades.includes(u.id)).map(u=>`<button class="upgrade-card" data-action="upgrade" data-upgrade="${u.id}"><strong>${esc(u.name)} →</strong><small>${esc(u.description)}</small><small>${esc(u.tradeoff)}</small></button>`).join('')+'</details><button class="secondary" data-action="next">收好东西，睡到明早 →</button>':'<button class="primary" data-action="finish">结束第三夜，看看这三天的故事 →</button>');
  }
  function firstWalkCard(){
    // Optional day-1 recommendation: exactly ONE current, feasible step.
    // Every button is an ordinary real action — free City travel or the real
    // one-preparation promise. The card never teleports, never enters the
    // nearest place while labelling it as the pub, and never grants rewards.
    if(state.phase!=='prep'||state.day!==1)return '';
    const promised=state.promises.lotte,used=state.prepared.includes('visit');
    const met=ui.city.visited.includes('lotte'),here=C.near(ui.city)?.id;
    const atPub=here==='pub';
    const toPub=cls=>`<button class="${cls}" data-action="city-travel" data-place="pub">${atPub?'进酒馆开门营业':'回酒馆开门'}</button>`;
    let title,line,main,aside='';
    if(promised){
      title='回酒馆，准备今晚开门';
      line='约定已记下：今晚给 Lotte 留一杯黑啤，开门会结束今天剩余的准备机会。';
      main=toPub('primary');
    }else if(used||state.actions<1){
      title='先回酒馆，或继续随便逛逛';
      line=used?'这件事今天已经办过；回酒馆开门是现在就能做的下一步。':'白天的准备机会用完了；漫游免费，回酒馆就能开门营业。';
      main=toPub('primary');
    }else if(!met){
      title='先去桥边听听 Lotte 的歌';
      line='她在酒馆旁的窄桥上排练；答应留一杯黑啤只需 1 次准备，不花钱。';
      main='<button class="primary" data-action="city-travel" data-place="lotte">沿运河走到桥边 · 漫游免费</button>';
      aside=toPub('secondary');
    }else{
      title='答应今晚给 Lotte 留一杯黑啤';
      line='只花 1 次准备，不花钱；晚上她来店里喝，乐队要等她真的到场。';
      main=here==='lotte'
        ?'<button class="primary" data-action="prepare" data-kind="visit">答应给 Lotte 留黑啤 · 1 次准备</button>'
        :'<button class="primary" data-action="city-travel" data-place="lotte">走回桥边找 Lotte · 漫游免费</button>';
      aside=toPub('secondary');
    }
    return `<div class="first-walk"><span class="board-eyebrow">第一天 · 可选推荐 / 只看当前这一步</span><h3>${title}</h3><p class="small-note">${line}</p>${main}${aside}</div>`;
  }
  function renderStreetBoard(headings){
    const late=state.phase==='summary';
