614	      case 'journey':{let value=data.value;if(value==='true')value=true;if(value==='false')value=false;if(data.verb==='dash')value=journey.direction();journey.do(data.verb,value);break;}
615	      case 'journey-return':dispatch({type:'journeyReturn'});break;
616	      case 'journey-debt':dispatch({type:'journeyDebt'});break;
617	      case 'expedition-launch':chooseExpedition();break;
618	      case 'exp-command':backstage.perform(data.verb);break;
619	      case 'start':{const n=Number($('seed-input')?.value);if(!Number.isInteger(n)||n<1||n>2147483647){notify('顾客安排请输入 1 到 2147483647 的整数。',true);return;}state=R.createGame(n);dispatch({type:'start'});break;}
620	      case 'city-travel':travelTo(data.place);break;
621	      case 'city-bike':if(inCity()&&!state.life.arrangement){const carrying=ui.city.bike.mounted||ui.city.bike.pushing;ui.city=C.toggleBike(ui.city);ui.cityMode='map';notify(ui.city.bike.pushing?'推着车过桥，到宽路上继续骑。':ui.city.bike.mounted?'骑上车了。宽桥直接过，窄桥自动推车。':carrying?'车停好了。回来按 B 就能带走。':'先靠近自行车。');save();render();}break;
622	      case 'city-bike-find':travelTo(null,ui.city.bike);break;
623	      case 'city-notebook':ui.notebook=!ui.notebook;render();break;
624	      case 'flower-start':dispatch({type:'flowerStart'});break;
625	      case 'flower-pick':dispatch({type:'flowerPick',stem:Number(data.stem)});break;
626	      case 'flower-wrap':dispatch({type:'flowerWrap',wrap:data.wrap});break;
627	      case 'flower-finish':dispatch({type:'flowerFinish'});break;
628	      case 'flower-cancel':dispatch({type:'flowerCancel'});break;
629	      case 'flower-store':if(nearBike())dispatch({type:'flowerStore',stored:!state.life.bouquet.stored});else notify('先走回停放自行车的位置。',true);break;
630	      case 'flower-use':if(ui.cityMode==='place'&&C.near(ui.city)?.id===(data.target==='display'?'pub':'lotte'))dispatch({type:'flowerUse',target:data.target});break;
631	      case 'city-map':if(state.life.arrangement)return;ui.cityMode='map';ui.cityKeys.clear();render();break;
632	      case 'city-overview':ui.cityCamera='city';ui.cityKeys.clear();render();break;
633	      case 'city-street':ui.cityCamera='street';ui.cityKeys.clear();render();break;
634	      case 'street-hint-close':ui.hintDismissed=true;render();break;
635	      case 'tutorial-dismiss':ui.tutorialSeen=true;save();render();break;
636	      case 'city-enter':enterCityPlace();break;
637	      case 'city-zoom':ui.cityZoom=ui.cityZoom===1?2:1;renderCityToolbar();break;
638	      case 'city-stop':ui.cityPath=[];ui.cityTarget=null;ui.cartFollowing=false;render();save();break;
639	      case 'brew':dispatch({type:'prepare',kind:'brew',beer:data.beer});break;
640	      case 'scout':if(inCity()&&ui.cityMode==='place'&&ui.cityPlace===data.place)dispatch({type:'scout',place:data.place});break;
641	      case 'prepare':dispatch({type:'prepare',kind:data.kind});break;
642	      case 'market-errand':
643	        if(state.phase==='prep'&&ui.cityMode==='place'&&ui.cityPlace==='market')dispatch({type:'marketErrand'});
644	        else notify('要白天亲自到超市，才能兑现这张回执。',true);
645	        break;
646	      case 'brew-hit':brewHit();break;
647	      case 'forage-move':dispatch({type:'forageMove',direction:Number(data.direction)});break;
648	      case 'forage-catch':dispatch({type:'forageCatch'});break;
649	      case 'dock':dispatch({type:'dock'});break;
650	      case 'cancel-brew':modal('这桶酒已经开始酿了','确定放弃这一批？','<p>€12 和这次准备机会已经花掉，放弃后不会有酒入库。</p>',[{label:'接着酿'},{label:'放弃这批酒',secondary:true,run:()=>dispatch({type:'cancelBrew'})}]);break;
651	      case 'open':if(state.actions>0)modal('天还没黑','现在就开始营业？',`<p>你还有 ${state.actions} 次准备机会。现在开门，这些机会不会留到明天。</p>`,[{label:'回去再准备一下'},{label:'现在开门',secondary:true,run:()=>dispatch({type:'open'})}]);else dispatch({type:'open'});break;
652	      case 'select':ui.selected=data.id;ui.beer=selectedCustomer()?.beer||'blond';ui.premium=false;ui.batchId=null;render();break;
653	      case 'beer':ui.beer=data.beer;ui.batchId=null;render();break;
654	      case 'price':ui.premium=data.premium==='true';render();break;
655	      case 'pour':pourForSelected();break;
656	      case 'serve':dispatch({type:'serve',customerId:data.id});break;
657	      case 'water':dispatch({type:'water',customerId:data.id});break;
658	      case 'close-night':modal('EARLY CLOSE','今晚就到这里？','<p>还在等候、以及尚未到店的客人，会错过这晚营业。答应 Lotte 的酒也要记得。</p>',[{label:'继续招待客人'},{label:'提前打烊',secondary:true,run:()=>dispatch({type:'close'})}]);break;
659	      case 'upgrade':dispatch({type:'upgrade',id:data.upgrade});break;
660	      case 'next':dispatch({type:'next'});break;
661	      case 'finish':dispatch({type:'finish'});break;
662	      case 'replay':restart(state.seed);break;
663	      case 'new-seed':restart(1+Math.floor(Math.random()*2147483646));break;
664	    }
665	  }
666	  document.addEventListener('click',e=>{
667	    const modalButton=e.target.closest('[data-modal-action]');
668	    if(modalButton&&ui.modal&&!modalButton.disabled){const callback=ui.modal.buttons[Number(modalButton.dataset.modalAction)].run;closeModal();if(callback)callback();syncEvent();return;}
669	    const button=e.target.closest('button[data-action]');if(button)handleAction(button);
670	  });
671	  $('help-button').addEventListener('click',showHelp);
672	  $('pause-button').addEventListener('click',()=>pause());
673	  $('sound-button').addEventListener('click',()=>{ui.sound=!ui.sound;save();render();if(ui.sound)sound();});
674	  document.addEventListener('keydown',e=>{
675	    if(ui.modal){
676	      if(e.key==='Escape'){e.preventDefault();if(ui.modal.kind==='event')return;const callback=ui.modal.buttons[0].run;closeModal();if(callback)callback();syncEvent();}
677	      if(e.key==='Tab'){const controls=[...$('overlay').querySelectorAll('button:not(:disabled),a,input')],first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
678	      return;
679	    }
680	    if(e.target.matches('input,textarea,select')){if(e.key==='Enter'&&e.target.id==='seed-input'){e.preventDefault();handleAction($board.querySelector('[data-action="start"]'));}return;}
681	    const key=e.key.toLowerCase();
682	    if(journey.key(e))return;
683	    if(backstage.key(e))return;
684	    if(inCity()&&!state.life.arrangement&&ui.cityMode==='map'&&['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(key)){e.preventDefault();const canceledRoute=ui.cityPath.length>0||ui.cityTarget!==null;ui.cityKeys.add(key);ui.cityPath=[];ui.cityTarget=null;ui.cartFollowing=false;if(canceledRoute)render();return;}
685	    if(e.repeat)return;
686	    if(key==='p'||key==='escape'){e.preventDefault();pause();return;}
687	    if(key==='h'){e.preventDefault();showHelp();return;}
688	    if(inCity()&&!state.life.arrangement){if(key==='b'){e.preventDefault();handleAction({dataset:{action:'city-bike'}});return;}if(key==='m'){e.preventDefault();if(ui.cityMode==='place')ui.cityMode='map';else ui.cityCamera=ui.cityCamera==='street'?'city':'street';render();return;}if(key==='e'&&ui.cityMode==='map'){e.preventDefault();enterCityPlace();return;}}
689	    if(state.phase==='brew'&&key===' '){e.preventDefault();brewHit();return;}
690	    if(state.phase==='forage'){
691	      if(['a','d','arrowleft','arrowright'].includes(key)){e.preventDefault();dispatch({type:'forageMove',direction:['a','arrowleft'].includes(key)?-1:1});return;}
692	      if(key===' '){e.preventDefault();dispatch({type:'forageCatch'});return;}
693	    }
694	    if(state.phase==='night'){
695	      if(['1','2','3'].includes(key)){e.preventDefault();const guest=R.customers(state)[Number(key)-1];if(guest){ui.selected=guest.id;ui.beer=guest.beer;ui.premium=false;render();}return;}
696	      if(key==='e'){e.preventDefault();pourForSelected();return;}
697	      if(key===' '){e.preventDefault();const pour=selectedPour()||state.night.pours[0];if(pour)dispatch({type:'serve',customerId:pour.customerId});return;}
698	    }
699	  });
700	  document.addEventListener('keyup',e=>ui.cityKeys.delete(e.key.toLowerCase()));
701	  window.addEventListener('blur',()=>ui.cityKeys.clear());
702	  $('pub-canvas').addEventListener('click',e=>{if(!inCity()||ui.cityMode!=='map'||ui.modal||state.life.arrangement)return;const box=e.currentTarget.getBoundingClientRect(),point=scene.cityWorldPoint((e.clientX-box.left)*1100/box.width,(e.clientY-box.top)*640/box.height);const place=C.near(point,85);if(place)travelTo(place.id);else travelTo(null,point);});
703	  document.addEventListener('visibilitychange',()=>{if(document.hidden){ui.cityKeys.clear();backstage.clear();journey.clear();save();if(['night','brew','forage','explore','journey'].includes(state.phase)||inCity()&&ui.cityPath.length)pause('你离开了一会儿，游戏已自动暂停。');}ui.lastFrame=performance.now();});
704	  window.addEventListener('pagehide',save);
705	  function frame(now){
706	    const seconds=Math.min(.1,Math.max(0,(now-ui.cityFrame)/1000));ui.cityFrame=now;
707	    if(inCity()&&ui.cityMode==='map'&&!ui.modal&&!document.hidden)stepCity(seconds);
708	    if(state.phase==='explore')backstage.step(seconds);else if(state.phase==='journey')journey.step(seconds);else scene.draw(state,now,ui.selected,cityView());updateMeters();requestAnimationFrame(frame);
709	  }
710	  setInterval(()=>{
711	    const now=performance.now(),seconds=Math.min(1,Math.max(0,(now-ui.lastFrame)/1000));ui.lastFrame=now;
712	    if(document.hidden||ui.modal)return;
713	    if(state.phase==='brew'){ui.brewElapsed+=seconds;if(ui.brewElapsed>=6)dispatch({type:'brewHit',score:0});}
714	    else if(state.phase==='night'||state.phase==='forage'){
715	      const before=state.phase;const result=R.act(state,{type:state.phase==='forage'?'forageTick':'tick',seconds});
716	      if(result.ok){state=result.state;if(signature()!==ui.signature){render();if(before!==state.phase){if(state.phase==='summary'){homeOnFoot();ui.cityMode='map';render();}save();notify(before==='forage'?state.lastMessage:'营业结束。看看今天的账，也看看谁记住了你。');sound('good');}}}
717	    }
718	    syncEvent();
719	    if(now-ui.lastSave>5000&&state.phase!=='welcome'){save();ui.lastSave=now;}
720	  },100);
721	  render();requestAnimationFrame(frame);
722	  if(restored&&['night','brew','forage','explore','journey'].includes(state.phase))pause('上次的进度已恢复。准备好后，从上次停下的地方继续。');
723	  else if(restored)notify('进度已恢复。打烊后就能进入夜间探险。');
724	  else if(saveError)notify('上次存档无法读取，已准备好一局新的开始。',true);
725	})();
