1	'use strict';
2	// PLAY02 / D22 presentation packet: real-module VM harness tests.
3	// Every test below executes the real reopening-ui / reopening-scene modules
4	// against states built with genuine actions and city movement. There are no
5	// source-substring searches and no forged rewards or auto-actions.
6	const { test } = require('node:test');
7	const assert = require('node:assert/strict');
8	const fs = require('node:fs');
9	const vm = require('node:vm');
10	const path = require('node:path');
11	const R = require('./reopening-core.js');
12	const City = require('./reopening-city.js');
13	
14	const noop = () => {};
15	function act(s, a) {
16	  const before = JSON.stringify(s);
17	  const r = R.act(s, a);
18	  assert.equal(JSON.stringify(s), before, 'act must not mutate its input');
19	  assert.ok(r.ok, (r.message || '') + ' :: ' + JSON.stringify(a));
20	  assert.ok(R.restore(r.state), 'result stays a valid save after ' + a.type);
21	  return r.state;
22	}
23	const start = (seed = 42) => act(R.createGame(seed), { type: 'start' });
24	const skipToNight = (seed = 42) => act(start(seed), { type: 'open' });
25	
26	// ---------------------------------------------------------------------------
27	// Full daytime UI VM harness (executes the real reopening-ui in a sandbox).
28	// ---------------------------------------------------------------------------
29	function harness(saved) {
30	  const gradient = { addColorStop: noop };
31	  const ctx = new Proxy({}, { get: (o, k) => (k === 'createLinearGradient' || k === 'createRadialGradient' ? () => gradient : noop), set: () => true });
32	  const mkEl = () => ({
33	    textContent: '', hidden: false, disabled: false, innerHTML: '', value: undefined,
34	    setAttribute: noop, removeAttribute: noop, addEventListener: noop, removeEventListener: noop,
35	    classList: { toggle: noop, add: noop, remove: noop }, style: {}, title: '', focus: noop,
36	    scrollIntoView: noop, querySelector: () => null, querySelectorAll: () => [], dataset: {}, remove: noop
37	  });
38	  const els = new Map();
39	  const listeners = {};
40	  const canvasListeners = {};
41	  const overlayEl = () => ({ ...mkEl(), hidden: true });
42	  const dialogActions = () => ({ ...mkEl(), querySelector: () => ({ focus: noop }) });
43	  const seedEl = () => ({ ...mkEl(), value: 42 });
44	  const canvasEl = () => ({ ...mkEl(), tabIndex: 0, getContext: () => ctx, getBoundingClientRect: () => ({ left: 0, top: 0, width: 1100, height: 640 }),
45	    addEventListener: (type, cb) => { (canvasListeners[type] = canvasListeners[type] || []).push(cb); } });
46	  const document = {
47	    addEventListener: (type, cb) => { (listeners[type] = listeners[type] || []).push(cb); },
48	    hidden: false, activeElement: { isConnected: false }, body: { classList: { toggle: noop } },
49	    getElementById(id) {
50	      if (id === 'pub-canvas') { if (!els.has(id)) els.set(id, canvasEl()); return els.get(id); }
51	      if (id === 'overlay') { if (!els.has(id)) els.set(id, overlayEl()); return els.get(id); }
52	      if (id === 'dialog-actions') { if (!els.has(id)) els.set(id, dialogActions()); return els.get(id); }
53	      if (id === 'seed-input') { if (!els.has(id)) els.set(id, seedEl()); return els.get(id); }
54	      if (!els.has(id)) els.set(id, mkEl());
55	      return els.get(id);
56	    },
57	    querySelector: () => null, querySelectorAll: () => []
58	  };
59	  let capturedSave = null;
60	  const localStorage = {
61	    getItem: () => (saved ? JSON.stringify(saved) : null),
62	    setItem: (k, v) => { capturedSave = JSON.parse(v); }
63	  };
64	  const rafs = [];
65	  let nowValue = 1000;
66	  const sandbox = {
67	    document, matchMedia: () => ({ matches: false }), localStorage,
68	    performance: { now: () => nowValue }, setTimeout: () => 0, clearTimeout: noop,
69	    setInterval: () => 0, requestAnimationFrame: cb => rafs.push(cb),
70	    devicePixelRatio: 1, location: { search: '' }, scrollTo: noop, addEventListener: noop,
71	    URLSearchParams: class { get() { return null; } }, navigator: {}, AudioContext: undefined, CSS: { escape: String }
72	  };
73	  sandbox.window = sandbox;
74	  vm.createContext(sandbox);
75	  const load = file => vm.runInContext(fs.readFileSync(path.join(__dirname, file), 'utf8'), sandbox);
76	  for (const file of ['journey-core.js', 'backstage-core.js', 'backstage-auto.js', 'delivery-orders.js',
77	    'character-stories.js', 'flower-network.js', 'reopening-core.js', 'reopening-city.js', 'reopening-scene.js',
78	    'backstage-scene.js', 'backstage-ui.js', 'journey-ui.js', 'reopening-ui.js']) load(file);
79	  const board = () => els.get('action-content').innerHTML;
80	  const queue = () => els.get('queue').innerHTML;
81	  const toolbar = () => els.get('city-toolbar').innerHTML;
82	  const overlay = () => els.get('overlay');
83	  const click = dataset => {
84	    const button = { dataset, disabled: false };
85	    const event = { target: { closest: sel => (sel === 'button[data-action]' ? button : null) } };
86	    for (const cb of listeners.click) cb(event);
87	  };
88	  const clickModal = index => {
89	    const button = { dataset: { modalAction: String(index) }, disabled: false };
90	    const event = { target: { closest: sel => (sel === '[data-modal-action]' ? button : null) } };
91	    for (const cb of listeners.click) cb(event);
92	  };
93	  // Pumps real requestAnimationFrame frames; movement uses real City movement.
94	  function pump(frames = 2000) {
95	    for (let i = 0; i < frames; i++) {
96	      nowValue += 100;
97	      const cb = rafs.shift();
98	      if (!cb) break;
99	      cb(nowValue);
100	    }
101	  }
102	  function travel(placeId, frames = 2000) {
103	    click({ action: 'city-travel', place: placeId });
104	    const name = City.PLACES[placeId].name;
105	    for (let i = 0; i < frames; i++) {
106	      nowValue += 100;
107	      const cb = rafs.shift();
108	      assert.ok(cb, 'frame scheduled while walking to ' + placeId);
109	      cb(nowValue);
110	      if (board().includes('<h2>' + name + '</h2>')) return;
111	    }
112	    assert.fail('never entered ' + placeId);
113	  }
114	  return {
115	    board, queue, toolbar, overlay, click, clickModal, travel,
116	    save: () => capturedSave, frames: pump,
117	    kicker: () => els.get('dialog-kicker').textContent,
118	    dialogBody: () => els.get('dialog-body').innerHTML
119	  };
120	}
121	
122	// ---------------------------------------------------------------------------
123	// Real PubScene renderer with a recording 2D context (no source inspection).
124	// ---------------------------------------------------------------------------
125	function sceneRig() {
126	  const marks = [];
127	  const transform = { scale: 1, tx: 0, ty: 0 };
128	  const target = {
129	    translate(x, y) { transform.tx = x; transform.ty = y; },
130	    scale(s) { transform.scale = s; }
131	  };
132	  const ctx = new Proxy(target, {
133	    get(o, k) {
134	      if (k in o) return o[k];
135	      if (k === 'createLinearGradient' || k === 'createRadialGradient') return () => ({ addColorStop: noop });
136	      return (...args) => marks.push([k, ...args]);
137	    },
138	    set: () => true
139	  });
140	  const sandbox = { window: { City }, matchMedia: () => ({ matches: false }), devicePixelRatio: 1 };
141	  sandbox.window.window = sandbox.window;
142	  vm.createContext(sandbox);
143	  vm.runInContext(fs.readFileSync(path.join(__dirname, 'reopening-scene.js'), 'utf8'), sandbox);
144	  const scene = new sandbox.window.PubScene({ width: 0, height: 0, getContext: () => ctx });
145	  const cityView = (position, extra) => ({ position, path: [], target: null, mode: 'map', notes: [], ...extra });
146	  const render = (position, extra) => scene.drawCity(cityView(position, extra), 0);
147	  const texts = () => marks.filter(m => m[0] === 'fillText').map(m => m[1]);
148	  return { scene, render, transform, texts, marks };
149	}
150	const cityAt = (x, y) => ({ ...City.create(), x, y });
151	
152	// The day-one recommendation card and the real datasets of its rendered buttons.
153	// Tests click the datasets parsed from the card markup rather than assuming one.
154	function walkCard(html) {
155	  const match = html.match(/<div class="first-walk">[\s\S]*?<\/div>/);
156	  assert.ok(match, 'first-walk recommendation card is rendered');
157	  return match[0];
158	}
159	const cardButtons = card => [...card.matchAll(/<button\b[^>]*>/g)].map(m => m[0]);
160	const buttonDataset = tag => ({
161	  action: (tag.match(/data-action="([^"]+)"/) || [])[1],
162	  place: (tag.match(/data-place="([^"]+)"/) || [])[1],
163	  kind: (tag.match(/data-kind="([^"]+)"/) || [])[1]
164	});
165	const countPrimary = card => (card.match(/class="primary"/g) || []).length;
166	const PUB_HEADING = '<h2>Tweede Kans</h2>';
167	
168	// ===========================================================================
