1	(function(root){
2	  'use strict';const B=root.Backstage,A=root.BackstageAuto;
3	  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
4	  class BackstageUI{
5	    constructor(options){
6	      Object.assign(this,options);this.keys=new Set();this.aim=null;this.pointer=null;this.overview=false;this.signature='';
7	      this.scene=new root.BackstageScene(this.canvas);
8	      this.canvas.addEventListener('pointermove',e=>{if(this.run()){this.trackPointer(e);}});
9	      this.canvas.addEventListener('pointerleave',()=>{this.pointer=null;this.aim=null;});
10	      this.canvas.addEventListener('pointerdown',e=>{
11	        if(!this.run()||this.isPaused()||this.run().auto?.enabled)return;e.preventDefault();this.canvas.focus({preventScroll:true});
12	        this.trackPointer(e);
13	        this.perform(e.button===2?'foam':'hook');
14	      });
15	      this.canvas.addEventListener('contextmenu',e=>{if(this.run())e.preventDefault();});
16	      document.addEventListener('pointerdown',e=>{
17	        const button=e.target.closest('[data-exp-move]');if(!button||!this.run()||this.isPaused()||this.run().auto?.enabled)return;
18	        e.preventDefault();button.setPointerCapture(e.pointerId);this.keys.add(button.dataset.expMove);this.aim=null;this.pointer=null;
19	      });
20	      for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,e=>{const button=e.target.closest('[data-exp-move]');if(button)this.keys.delete(button.dataset.expMove);});
21	      document.addEventListener('keyup',e=>this.keys.delete(e.key.toLowerCase()));
22	      window.addEventListener('blur',()=>this.clear());
23	    }
24	    run(){return this.getState().phase==='explore'?this.getState().backstage.run:null;}
25	    trackPointer(e){const box=this.canvas.getBoundingClientRect();this.pointer={x:(e.clientX-box.left)*1100/box.width,y:(e.clientY-box.top)*640/box.height};this.updateAim();}
26	    updateAim(){this.aim=this.pointer&&!this.run()?.auto?.enabled?this.scene.worldPoint(this.pointer.x,this.pointer.y,this.run(),this.overview):null;}
27	    clear(){this.keys.clear();this.aim=null;this.pointer=null;}
28	    key(e){
29	      if(!this.run()||this.isPaused())return false;
30	      const k=e.key.toLowerCase();
31	      if(this.run().auto?.enabled&&k!=='m'){
32	        if(/^[1-9]$/.test(k)){e.preventDefault();const choice=A.view(this.run()).choices[Number(k)-1];if(choice&&!e.repeat)this.perform('choice:'+choice.id);return true;}
33	        if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e','j','f','n','r','q',' '].includes(k)){e.preventDefault();return true;}
34	        return false;
35	      }
36	      if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();this.keys.add(k);return true;}
37	      const verb={e:'interact',j:'hook',f:'foam',n:'lure',r:'drag',q:'drop',' ':'dash',m:'map'}[k];
38	      if(verb){e.preventDefault();if(!e.repeat)this.perform(verb);return true;}return false;
39	    }
40	    perform(verb){
41	      const r=this.run();if(!r||this.isPaused())return;
42	      this.updateAim();
43	      if(verb==='cargo'){
44	        const kinds=new Set(),choices=[];
45	        for(const id of r.bag){const item=r.items.find(i=>i.id===id);if(kinds.has(item.kind))continue;kinds.add(item.kind);const t=B.TYPES[item.kind];choices.push({label:'放下'+t.name,description:'腾出 '+t.weight+' 格 · 扔在脚边，仍能追回',secondary:true,run:()=>this.perform('cargo-drop:'+id)});}
46	        this.showModal('背包 / 时间暂停','什么值得带回去？','<p>放下的东西会落在街区，不会直接换钱。修温室水泵需要一件可修零件。</p>',[{label:'先都留着，继续探索'},...choices]);return;
47	      }
48	      if(verb.startsWith('cargo-drop:')){
49	        const id=verb.slice(11);
50	        if(r.auto?.enabled&&r.auto.event==='capacity')A.choose(r,'drop-'+id);
51	        else B.command(r,'drop',{x:r.p.x-r.p.fx*90,y:r.p.y-r.p.fy*90,itemId:id});
52	        this.signature='';this.save();this.render();return;
53	      }
54	      if(verb==='play'){
55	        if(r.auto?.event){const choice=document.querySelector('.exp-choices button');choice?.scrollIntoView({block:'center',behavior:'auto'});choice?.focus({preventScroll:true});}
56	        else this.showModal('PAUSED · 探索已暂停','先停在这里。','<p>角色、街区和倒计时都暂停了。继续后沿原来的路线走。</p>',[{label:'继续探索'}]);
57	        return;
58	      }
59	      if(verb==='map'){this.overview=!this.overview;this.render();return;}
60	      if(verb==='return'){this.clear();this.dispatch({type:'returnExplore'});return;}
61	      if(verb==='mode'||verb==='reroute'||verb==='speed'||verb.startsWith('choice:')){
62	        this.clear();
63	        if(verb==='mode'){if(r.auto?.enabled)A.disable(r);else A.enable(r);}
64	        else if(verb==='reroute')A.enable(r);
65	        else if(verb==='speed'&&r.auto?.enabled)r.auto.speed=r.auto.speed===1?2:1;
66	        else if(verb.startsWith('choice:'))A.choose(r,verb.slice(7));
67	        this.signature='';this.save();this.render();return;
68	      }
69	      if(verb==='bail'){
70	        this.showModal('轻装撤回','放下背包，先回家？','<p>本趟尚未带回的物品会留在街区。已经交给 Noor 的箱子、发现的地点和家中积累都会保留。</p>',[
71	          {label:'继续探险'},{label:'放下背包，撤回',secondary:true,run:()=>this.perform('confirm-bail')}
72	        ]);return;
73	      }
74	      if(r.auto?.enabled&&verb!=='confirm-bail')return;
75	      B.command(r,verb==='confirm-bail'?'bail':verb,this.aim);this.signature='';this.save();this.render();
76	    }
77	    step(seconds){
78	      const r=this.run();if(!r)return;
79	      this.updateAim();
80	      if(!this.isPaused()&&!document.hidden&&r.status==='active'){
81	        if(r.auto?.enabled){const before=[r.auto.event,r.status].join('|');A.step(r,seconds);if(before!==[r.auto.event,r.status].join('|'))this.save();}
82	        else{
83	          const dx=Number(this.keys.has('d')||this.keys.has('arrowright'))-Number(this.keys.has('a')||this.keys.has('arrowleft'));
84	          const dy=Number(this.keys.has('s')||this.keys.has('arrowdown'))-Number(this.keys.has('w')||this.keys.has('arrowup'));
85	          B.step(r,{dx,dy,aim:this.aim},seconds);
86	        }
87	      }
88	      const beat=Math.floor(r.time*2);
