      document.getElementById('exp-play-state').textContent=r.status!=='active'?'这一趟已结束':this.isPaused()?'Ⅱ 已暂停':auto?(r.auto.event?'Ⅱ 等你选择 · 时间暂停':'▶ 自动探索中'):'手动操作';
