254	    if(a.goal==='sorting-reverse'&&dist(r.p,to)<18&&r.p.hook>0){B.step(r,{},dt);a.legTime+=dt;return;}
255	    if(lootGoal(a.goal)&&dist(r.p,to)<45&&B.clear(r,r.p,to)){arrived(r);return;}
256	    if(a.goal==='music'){
257	      const club=B.locationInfo(r).club;
258	      if(club?.loud&&club.remaining>=2.5){go(r,'parcel');return;}
259	      B.step(r,{},dt);a.legTime+=dt;return;
260	    }
261	    if(a.goal==='club'&&r.parcel!=='ground'){stop(r,'route');return;}
262	    if(a.goal==='parcel'&&r.parcel!=='ground'){stop(r,r.parcel==='carried'?'parcel':'route');return;}
263	    if(!lootGoal(a.goal)&&!MARKET_AUTO_GOALS.includes(a.goal)&&(a.goal==='parcel'?B.nearest(r)?.id===to.id:dist(r.p,to)<(a.goal==='barricade'?7:18))){arrived(r);return;}
264	    if(['noor','sorting'].includes(a.goal)&&a.legTime>.5&&!r.discovered.includes('greenhouse')&&!a.visited.includes('glimpse')&&dist(r.p,B.flowerCart(r))<150&&B.clear(r,r.p,B.flowerCart(r))){a.visited.push('glimpse');a.event='glimpse';return;}
265	    const threat=r.actors.filter(o=>['cleaner','guard'].includes(o.type)&&o.stun<=.1&&(a.approach!=='lure'||o.mode!=='investigate')&&dist(r.p,o)<(a.approach==='music'&&a.goal==='parcel'?55:185)&&B.clear(r,r.p,o)).sort((x,y)=>dist(r.p,x)-dist(r.p,y))[0];
266	    if(threat){
267	      if(a.approach==='hook'&&r.p.hook===0)B.command(r,'hook',threat);
268	      else if(r.p.foam===0)B.command(r,'foam',threat);
269	      else if(r.p.hook===0)B.command(r,'hook',threat);
270	    }else if(a.goal==='parcel'&&a.approach==='hook'&&dist(r.p,to)<B.KITS[r.kit].range&&r.p.hook===0)B.command(r,'hook',to);
271	    if(a.goal==='sorting-hook'&&r.p.hook===0&&dist(r.p,to)<B.KITS[r.kit].range&&B.clear(r,r.p,to))B.command(r,'hook',to);
272	    if(a.goal==='sorting-foam'&&r.p.foam===0&&dist(r.p,to)<200&&B.clear(r,r.p,to))B.command(r,'foam',to);
273	    let cached=routes.get(r);
274	    if(!cached||dist(cached.to,to)>25||cached.opened!==r.opened||!cached.path.length||!clearWalk(r,r.p,cached.path[0])){
275	      cached={path:route(r,to,lootGoal(a.goal)||marketLootGoal(a.goal)?40:0),to:{x:to.x,y:to.y},opened:r.opened};routes.set(r,cached);
276	    }
277	    const path=cached.path;
278	    while(path.length>1&&clearWalk(r,r.p,path[1]))path.shift();
279	    while(path.length>1&&dist(r.p,path[0])<10)path.shift();
280	    if(!path.length||a.legTime>40){stop(r,'stuck');return;}
281	    const point=path[0],length=Math.max(1,dist(r.p,point));B.step(r,{dx:(point.x-r.p.x)/length,dy:(point.y-r.p.y)/length},dt);a.legTime+=dt;
282	  }
283	  function step(r,seconds){
284	    if(!r?.auto?.enabled||r.auto.event||r.status!=='active'||!Number.isFinite(seconds)||seconds<=0)return;
285	    let remaining=Math.min(.1,seconds)*r.auto.speed;
286	    while(remaining>1e-8&&r.status==='active'&&!r.auto.event){const dt=Math.min(.025,remaining);remaining-=dt;tick(r,dt);}
287	  }
288	  return Object.freeze({enable,disable,choose,step,view,valid});
289	});
