  S.open(state,orders);
  return { elapsed: 0, duration, orders, pours: [], earned: 0, served: 0, satisfied: 0, lost: 0, promiseKept: false, promiseBroken: false, event: null, rentAdjustment: 0 };
}
function breakPromise(state, order) {
