        const next=state.night.orders.filter(o=>o.status==='future').sort((a,b)=>a.arrival-b.arrival)[0];
        $('queue').innerHTML=`<div class="guest-empty"><strong>片刻安静。</strong><span>${next?'下一位客人正在路上。可以查看库存，准备接单。':'最后一杯已经送出。'}</span></div>`;
