test('loadout dialog shows short essentials, tonight title, closed details with full facts and verbatim kit cards', () => {
  const h = nightLoadout();
  assert.equal(h.kicker(), '出门前 · 工具免费借用');
  assert.equal(h.dialogTitle(), '今晚带哪一套？');
